  [("Medir el giro", "Haces dos medias vueltas seguidas sobre la línea. ¿Cuántos grados giraste y cómo quedas mirando?", ["Cada media vuelta mide 180°.", "180° + 180° = 360°.", "Una vuelta completa te deja mirando al mismo lado del inicio."], "360°; quedas mirando al mismo lado del inicio"),
   ("Corregir una inclinación", "Al girar sientes que el cuerpo se inclina hacia tu izquierda. ¿Qué haces con el centro del cuerpo?", ["Si me inclino a la izquierda, el cuerpo se sale de la línea.", "Llevo el centro del cuerpo de vuelta al medio, hacia la derecha, y bajo un poco las rodillas.", "Así recupero el equilibrio."], "Llevas el centro del cuerpo de vuelta al medio, hacia la derecha")],
  [("Girar con los pies primero y los hombros después.", "El cuerpo se tuerce y pierdes el punto fijo.", "Sigue el orden: mirada, hombros, cadera y pies."), ("Hacer cuatro giros seguidos muy rápido.", "Puedes marearte y caerte.", "Haz máximo 2 giros seguidos y descansa.")],
