  [ex("Camila giró media vuelta en 4 intentos sin salirse de la línea. Joaquín giró vuelta completa en 4 intentos y se salió en 3. ¿Quién mostró más control en el giro?", "Camila", "No se salió de la línea en ningún intento."),
   ex("Tomás dice: «Si giro mucho más rápido ganaré equilibrio». ¿Es correcto?", "No", "Más velocidad quita control; el giro se hace despacio.")],
