  [("variante accesible", "versión de un ejercicio con un cambio que permite hacerlo con control"), ("precisión", "cuántos lanzamientos llegan adonde quería"), ("porcentaje de aciertos", "cuántos lanzamientos entran de cada 100"), ("nivel", "cada grado de dificultad: más fácil, medio o más difícil"), ("ronda", "serie de lanzamientos seguidos antes de descansar")],
